"""Bahasa Melayu — akhlak (virtues_001 … virtues_050)."""

T = {
"virtues_001": ("Menurut hadis yang diriwayatkan Imam al-Bukhari, apakah yang perlu dilakukan orang yang beriman kepada Allah dan hari Akhirat dengan percakapannya?", ["Berkata baik atau diam", "Bercakap dengan kuat", "Tidak pernah bercakap", "Mengulang khabar angin"], "Nabi ﷺ bersabda: «Sesiapa yang beriman kepada Allah dan hari Akhirat, hendaklah dia berkata baik atau diam.»"),
"virtues_002": ("Menurut hadis yang sama, siapakah lagi yang perlu dimuliakan orang beriman, selain tetamunya?", ["Jirannya", "Pedagangnya", "Saingannya", "Orang asing"], "Hadis itu bersambung: «…dan sesiapa yang beriman kepada Allah dan hari Akhirat, hendaklah dia memuliakan jirannya.»"),
"virtues_003": ("Hadis yang sama juga menyebut memuliakan siapa, apabila dia datang ke rumah kita?", ["Tetamu", "Hanya jiran", "Pedagang", "Musafir asing yang jauh"], "Hadis lengkapnya berbunyi: «…sesiapa yang beriman kepada Allah dan hari Akhirat, hendaklah dia memuliakan tetamunya.»"),
"virtues_004": ("Menurut hadis sahih, iman seseorang tidak sempurna sehingga dia mencintai untuk saudaranya apa yang dia cintai untuk…", ["dirinya sendiri", "hartanya", "keluarganya sahaja", "negaranya"], "Nabi ﷺ bersabda: «Tidak beriman seseorang daripada kamu sehingga dia mencintai untuk saudaranya apa yang dia cintai untuk dirinya sendiri.»"),
"virtues_005": ("Menurut hadis sahih, Muslim sejati ialah orang yang orang lain selamat daripada lidah dan ___-nya.", ["tangan", "harta", "pandangan", "suara"], "Nabi ﷺ bersabda: «Muslim ialah orang yang orang Islam lain selamat daripada lidah dan tangannya.»"),
"virtues_006": ("Al-Quran memerintahkan berbuat baik kepada ibu bapa dan melarang mengucapkan perkataan kesal apa kepada mereka?", ["«Ah» (ungkapan tidak sabar)", "«Tidak»", "«Cukup»", "«Tunggu»"], "Al-Quran menyeru kebaikan yang tertinggi kepada ibu bapa, malah melarang perkataan penghinaan yang paling ringan."),
"virtues_007": ("Dengan apakah al-Quran mengumpamakan mengumpat (bercakap buruk tentang orang yang tiada)?", ["Memakan daging saudaranya yang telah mati", "Meminum air masin", "Berjalan dalam kegelapan", "Menanam di pasir"], "«Adakah seseorang daripada kamu suka memakan daging saudaranya yang telah mati? Sudah tentu kamu jijik!»: begitulah buruknya mengumpat."),
"virtues_008": ("Bagaimanakah al-Quran menggambarkan hubungan antara orang beriman?", ["Mereka bersaudara", "Mereka bersaing", "Mereka saling asing", "Mereka rakan perniagaan"], "«Sesungguhnya orang mukmin itu bersaudara, maka damaikanlah antara dua saudara kamu.»"),
"virtues_009": ("Apakah yang al-Quran katakan tentang memperolok-olokkan orang lain?", ["Dilarang: yang diperolok-olokkan boleh jadi lebih baik daripada yang memperolok-olokkan", "Dibenarkan antara rakan", "Dibenarkan jika lucu", "Khusus untuk penyair"], "«Janganlah sesuatu kaum memperolok-olokkan kaum yang lain, boleh jadi mereka lebih baik daripada mereka.»"),
"virtues_010": ("Menurut al-Quran, apakah yang Allah janjikan kepada orang yang bersyukur?", ["Dia pasti akan menambah nikmat-Nya", "Umur yang panjang", "Kekayaan serta-merta", "Satu perjalanan"], "«Jika kamu bersyukur, nescaya Aku akan menambah nikmat kepada kamu.»"),
"virtues_011": ("Menurut al-Quran, bagaimanakah orang yang sabar akan diberi ganjaran?", ["Dengan sempurna, tanpa batas", "Sekaligus", "Selepas empat puluh hari", "Mengikut kekayaannya"], "«Sesungguhnya hanya orang yang sabar yang disempurnakan ganjaran mereka tanpa batas.»"),
"virtues_012": ("«Makan dan minumlah, tetapi…»: bagaimanakah ayat ini bersambung?", ["Jangan berlebih-lebihan", "Jangan berkongsi", "Jangan bercakap", "Jangan keluar"], "«Makan dan minumlah, tetapi jangan berlebih-lebihan; sesungguhnya Allah tidak menyukai orang yang berlebih-lebihan.»"),
"virtues_013": ("Ayat manakah, yang sering dibaca dalam khutbah Jumaat, merumuskan apa yang Allah perintahkan?", ["«Allah memerintahkan berlaku adil dan berbuat kebaikan»", "«Allah memerintahkan berdagang»", "«Allah memerintahkan bermusafir»", "«Allah memerintahkan diam»"], "«Sesungguhnya Allah menyuruh berlaku adil, berbuat kebaikan, dan memberi kepada kaum kerabat…»: dibaca setiap Jumaat."),
"virtues_014": ("Terhadap siapakah surah Al-Mutaffifin dibuka dengan «Celakalah…»?", ["Orang yang menipu dalam sukatan dan timbangan", "Orang yang tidur", "Orang yang bermusafir", "Orang yang diam"], "«Celakalah orang yang curang dalam sukatan: yang apabila menerima sukatan daripada orang lain mereka minta dicukupkan, dan apabila menyukat untuk orang lain mereka mengurangkan.»"),
"virtues_015": ("Menurut surah Ad-Dhuha, bagaimanakah anak yatim dan orang yang meminta perlu dilayan?", ["Tidak ditindas dan tidak dihalau", "Diabaikan", "Dihantar kepada orang lain", "Diajak bercakap kemudian"], "«Maka terhadap anak yatim janganlah engkau berlaku sewenang-wenangnya, dan terhadap orang yang meminta janganlah engkau menghalau.»"),
"virtues_016": ("Bagaimanakah al-Quran memerintahkan kita bercakap dengan manusia?", ["Dengan kata-kata yang baik", "Dengan suara yang sangat perlahan", "Sesedikit mungkin", "Hanya dengan saudara-mara"], "«…dan bercakaplah kepada manusia dengan kata-kata yang baik»: percakapan yang baik itu sendiri ialah ibadah."),
"virtues_017": ("Dalam nasihatnya kepada anaknya, apakah yang Luqman katakan tentang berjalan dan kesombongan?", ["Jangan berjalan di bumi dengan angkuh", "Sentiasa berjalan pantas", "Hanya berjalan pada waktu malam", "Jangan pernah berjalan seorang diri"], "«Janganlah engkau memalingkan mukamu daripada manusia kerana sombong, dan janganlah berjalan di bumi dengan angkuh.»"),
"virtues_018": ("Menurut hadis pertama dalam himpunan al-Bukhari, dengan apakah amalan dinilai?", ["Niat", "Hasil", "Kebiasaan", "Saksi"], "«Sesungguhnya setiap amalan bergantung pada niat, dan setiap orang hanya mendapat apa yang dia niatkan.»"),
"virtues_019": ("Menurut hadis dalam al-Bukhari, ke manakah kejujuran (sidq) membawa?", ["Kepada kebaikan, dan kebaikan membawa ke syurga", "Kepada kekayaan", "Kepada kemasyhuran", "Kepada kekuatan"], "«Kejujuran membawa kepada kebaikan, dan kebaikan membawa ke syurga; dusta membawa kepada kejahatan, dan kejahatan membawa ke neraka.»"),
"virtues_020": ("Menurut hadis sahih, apakah tiga tanda orang munafik?", ["Apabila bercakap dia berdusta, apabila berjanji dia mungkir, apabila diamanahkan dia khianat", "Dia tidur, makan dan bercakap terlalu banyak", "Dia bermusafir, berdagang dan menyanyi", "Dia sedikit solat, sedikit puasa dan sedikit membaca"], "«Tanda orang munafik ada tiga: apabila bercakap dia berdusta, apabila berjanji dia mungkir, dan apabila diamanahkan dia khianat.»"),
"virtues_021": ("Seorang lelaki meminta nasihat daripada Nabi ﷺ; apakah yang baginda ulangi kepadanya beberapa kali?", ["«Jangan marah»", "«Banyakkan bermusafir»", "«Makanlah sedikit»", "«Bercakaplah dengan kuat»"], "Lelaki itu berkata: «Nasihatilah aku.» Baginda menjawab: «Jangan marah.» Lelaki itu bertanya lagi, dan baginda mengulangi: «Jangan marah.»"),
"virtues_022": ("Menurut Nabi ﷺ, siapakah yang benar-benar kuat?", ["Orang yang dapat menguasai dirinya ketika marah", "Orang yang menang bergusti", "Orang yang memikul beban paling berat", "Orang yang berlari paling pantas"], "«Orang yang kuat bukanlah yang menang bergusti; orang yang kuat ialah yang dapat menguasai dirinya ketika marah.»"),
"virtues_023": ("Menurut hadis dalam al-Bukhari, sifat malu (haya') ialah sebahagian daripada apa?", ["Iman", "Kelemahan", "Kekayaan", "Sifat pemalu yang tercela"], "Melihat seorang lelaki menegur saudaranya kerana sifat malunya, Nabi ﷺ bersabda: «Biarkan dia, kerana malu itu sebahagian daripada iman.»"),
"virtues_024": ("Apakah yang Nabi ﷺ katakan kepada seorang lelaki yang berbangga tidak pernah mencium seorang pun daripada sepuluh anaknya?", ["«Sesiapa yang tidak menyayangi, dia tidak akan disayangi»", "«Engkau benar»", "«Anak-anak tidak penting»", "«Itu urusan peribadi»"], "Nabi ﷺ biasa mencium cucu-cucunya; kepada Al-Aqra' yang hairan, baginda menjawab: «Man la yarham la yurham.»"),
"virtues_025": ("Menurut hadis dalam al-Bukhari, kerana amalan apakah seorang lelaki diampuni?", ["Kerana memberi minum anjing yang kehausan", "Kerana membina perigi", "Kerana menanam pokok", "Kerana menghalau serigala"], "Lelaki itu turun ke dalam perigi, mengisi kasutnya dengan air dan memberikannya kepada anjing yang termengah-mengah kehausan; Allah mengampuninya."),
"virtues_026": ("Menurut hadis sahih, mengapakah seorang wanita diseksa?", ["Kerana mengurung kucing tanpa memberinya makan atau membiarkannya mencari makan", "Kerana menjual kucing", "Kerana menghalau kucing dari rumahnya", "Kerana memelihara terlalu banyak kucing"], "«Seorang wanita diseksa kerana seekor kucing yang dia kurung sehingga mati: dia tidak memberinya makan dan tidak membiarkannya makan daripada binatang-binatang bumi.»"),
"virtues_027": ("Tentang siapakah Nabi ﷺ bersabda bahawa Jibril terus berpesan kepadanya sehingga baginda menyangka dia akan dijadikan waris?", ["Jiran", "Tetamu", "Anak yatim", "Musafir"], "«Jibril terus berpesan kepadaku tentang jiran, sehingga aku menyangka dia akan menjadikannya waris.»"),
"virtues_028": ("Menurut hadis dalam al-Bukhari, berapakah hak seorang Muslim ke atas Muslim yang lain?", ["Lima", "Tiga", "Tujuh", "Sepuluh"], "«Menjawab salam, menziarahi orang sakit, mengiringi jenazah, memenuhi jemputan, dan mendoakan orang yang bersin.»"),
"virtues_029": ("Apabila ditanya «Islam yang manakah yang terbaik?», apakah jawapan Nabi ﷺ?", ["Memberi makan dan memberi salam kepada orang yang dikenali dan yang tidak dikenali", "Membina masjid", "Banyak bermusafir", "Sedikit bercakap"], "«Memberi makan, dan memberi salam kepada orang yang engkau kenali dan yang tidak engkau kenali.»"),
"virtues_030": ("Dengan apakah Nabi ﷺ mengumpamakan orang beriman dalam kasih sayang dan saling membantu mereka?", ["Satu tubuh: jika satu anggota sakit, seluruh tubuh berjaga dan demam", "Sebuah hutan", "Sebuah kafilah", "Sekawan ternakan"], "«Perumpamaan orang beriman dalam saling mencintai, menyayangi dan mengasihi ialah seperti satu tubuh.»"),
"virtues_031": ("Menurut Nabi ﷺ, apakah «percakapan yang paling dusta»?", ["Prasangka (zhan)", "Syair", "Gurauan", "Diam"], "«Jauhilah prasangka, kerana prasangka ialah percakapan yang paling dusta.»"),
"virtues_032": ("Menurut hadis sahih, paling lama berapa hari seorang Muslim boleh memulaukan saudaranya?", ["Tiga hari", "Tujuh hari", "Sebulan", "Setahun"], "«Tidak halal bagi seorang lelaki memulaukan saudaranya lebih daripada tiga malam… dan yang terbaik antara keduanya ialah yang memulakan salam.»"),
"virtues_033": ("Menurut Nabi ﷺ, apakah nilai setiap kebaikan, sekecil mana pun?", ["Ia adalah sedekah", "Ia tidak dikira", "Ia bernilai satu dinar", "Ia menggantikan solat"], "«Setiap kebaikan adalah sedekah.»"),
"virtues_034": ("Menurut hadis dalam Sahih Muslim, apakah cabang iman yang paling rendah?", ["Menyingkirkan gangguan dari jalan", "Membina masjid", "Membaca satu juzuk", "Berpuasa sehari"], "«Iman mempunyai tujuh puluh sekian cabang: yang tertinggi ialah 'la ilaha illallah', yang terendah ialah menyingkirkan gangguan dari jalan; dan malu ialah satu cabang iman.»"),
"virtues_035": ("Menurut hadis dalam Sahih Muslim, kesucian (taharah) ialah…?", ["Separuh daripada iman", "Sepertiga daripada iman", "Sepersepuluh daripada iman", "Tiada kaitan dengan iman"], "«Kesucian ialah separuh daripada iman, dan 'alhamdulillah' memenuhi neraca.»"),
"virtues_036": ("Nabi ﷺ bersabda: «Agama itu nasihat (keikhlasan)»: kepada siapa?", ["Kepada Allah, Kitab-Nya, Rasul-Nya, para pemimpin dan seluruh orang Islam", "Hanya kepada diri sendiri", "Kepada orang kaya", "Kepada orang asing"], "Mereka bertanya: «Kepada siapa?» Baginda bersabda: «Kepada Allah, Kitab-Nya, Rasul-Nya, para pemimpin orang Islam dan orang awam mereka.»"),
"virtues_037": ("Menurut hadis dalam Sahih Muslim, apakah yang Allah lihat pada hamba-hamba-Nya?", ["Hati dan amalan mereka", "Rupa mereka", "Harta mereka", "Jumlah mereka"], "«Allah tidak melihat tubuh dan rupa kamu, tetapi Dia melihat hati dan amalan kamu.»"),
"virtues_038": ("Menurut hadis dalam Sahih Muslim, apakah yang Allah lakukan bagi orang yang melapangkan kesusahan dunia seorang mukmin?", ["Dia melapangkan kesusahannya pada hari Kiamat", "Dia menjadikannya kaya", "Dia memberinya umur panjang", "Dia menjadikannya terkenal"], "«Sesiapa yang melapangkan satu kesusahan dunia daripada seorang mukmin, Allah akan melapangkan daripadanya satu kesusahan pada hari Kiamat.»"),
"virtues_039": ("Menurut Nabi ﷺ, apakah yang Allah lakukan bagi orang yang menempuh jalan untuk mencari ilmu?", ["Dia memudahkan baginya jalan ke syurga", "Dia membebaskannya daripada solat", "Dia menjadikannya kaya", "Dia menjadikannya raja"], "«Sesiapa yang menempuh jalan untuk mencari ilmu, Allah akan memudahkan baginya jalan ke syurga.»"),
"virtues_040": ("Menurut hadis dalam al-Bukhari, siapakah «sebaik-baik kamu»?", ["Orang yang mempelajari al-Quran dan mengajarkannya", "Orang yang paling petah bercakap", "Orang yang paling banyak harta", "Orang yang paling banyak bermusafir"], "«Sebaik-baik kamu ialah orang yang mempelajari al-Quran dan mengajarkannya.»"),
"virtues_041": ("Bagaimanakah Nabi ﷺ mentakrifkan kesombongan (kibr)?", ["Menolak kebenaran dan memandang rendah manusia", "Memakai pakaian yang cantik", "Menyukai kasut yang cantik", "Berjalan pantas"], "Kepada lelaki yang menyukai pakaian cantik baginda bersabda: «Allah itu indah dan menyukai keindahan. Kesombongan ialah menolak kebenaran dan memandang rendah manusia.»"),
"virtues_042": ("Menurut hadis dalam al-Bukhari, dua nikmat apakah yang ramai orang rugi di dalamnya?", ["Kesihatan dan masa lapang", "Wang dan kemasyhuran", "Kekuatan dan kecantikan", "Keluarga dan rakan"], "«Ada dua nikmat yang ramai manusia rugi di dalamnya: kesihatan dan masa lapang.»"),
"virtues_043": ("Lengkapkan hadis ini: «Seorang mukmin tidak disengat dua kali…»", ["«…dari lubang yang sama»", "«…oleh kala jengking yang sama»", "«…pada hari yang sama»", "«…oleh lebah yang sama»"], "«La yuldaghul-mu'minu min juhrin wahidin marratain»: orang beriman belajar daripada kesilapannya."),
"virtues_044": ("Dengan apakah Nabi ﷺ mengumpamakan rakan yang baik, berbeza dengan tukang besi?", ["Penjual minyak kasturi", "Tukang roti", "Penggembala", "Peniaga kain"], "«Rakan yang baik seperti pembawa minyak kasturi: dia memberimu, atau engkau membeli daripadanya, atau engkau mencium haruman darinya; rakan yang buruk seperti peniup api tukang besi.»"),
"virtues_045": ("Menurut hadis dalam al-Bukhari, atas apakah setiap kita bertanggungjawab «seperti penggembala»?", ["Atas orang yang berada di bawah jagaan kita", "Atas cuaca", "Atas bintang-bintang", "Atas hasil tanaman orang lain"], "«Setiap kamu adalah pemimpin, dan setiap kamu bertanggungjawab atas yang dipimpinnya»: pemerintah atas rakyatnya, suami atas keluarganya, isteri atas rumah tangganya."),
"virtues_046": ("Menurut al-Quran, apakah yang berlaku jika kejahatan ditolak dengan cara yang lebih baik?", ["Orang yang dahulunya musuh menjadi seperti sahabat yang setia", "Kejahatan lenyap dari bumi", "Seseorang menjadi kaya", "Tiada apa yang berubah"], "«Tolaklah kejahatan itu dengan cara yang lebih baik, maka orang yang ada permusuhan antaramu dengannya akan menjadi seperti sahabat yang setia» (41:34)."),
"virtues_047": ("Bagaimanakah «hamba-hamba Tuhan Yang Maha Pemurah» menjawab orang jahil yang mengganggu mereka, menurut surah Al-Furqan?", ["Mereka mengucapkan: «Salam!»", "Mereka membalas dengan marah", "Mereka memperolok-olokkannya", "Mereka memukulnya"], "«Hamba-hamba Tuhan Yang Maha Pemurah ialah orang yang berjalan di bumi dengan rendah hati, dan apabila orang jahil menyapa mereka, mereka mengucapkan: Salam!» (25:63)."),
"virtues_048": ("Apakah yang al-Quran katakan tentang janji?", ["«Penuhilah janji, sesungguhnya janji itu pasti akan dipersoalkan»", "«Janji tidak mengikat sesiapa»", "«Hanya berjanjilah kepada orang kaya»", "«Jangan pernah berjanji»"], "«Dan penuhilah janji, sesungguhnya janji itu pasti akan dipersoalkan» (17:34)."),
"virtues_049": ("Tentang siapakah al-Quran mengatakan bahawa mereka «saudara-saudara syaitan»?", ["Orang yang membazir", "Para musafir", "Para pedagang", "Para penyair"], "«Sesungguhnya orang yang membazir itu adalah saudara syaitan, dan syaitan itu sangat ingkar kepada Tuhannya» (17:27)."),
"virtues_050": ("Apakah «dua kalimah yang ringan di lidah, berat di neraca, dan dicintai oleh Yang Maha Pemurah»?", ["«Subhanallahi wa bihamdih, subhanallahil 'azim»", "«Allahu akbar, alhamdulillah»", "«La ilaha illallah, Muhammadur rasulullah»", "«Bismillah, masya Allah»"], "«Dua kalimah yang ringan di lidah, berat di neraca, dicintai oleh Yang Maha Pemurah: Maha Suci Allah dan segala puji bagi-Nya; Maha Suci Allah Yang Maha Agung.»"),
}
